<script setup>
import {ref,computed,onBeforeUnmount} from 'vue';
import {Button,Cell,CellGroup,Collapse,CollapseItem,Field,Popup,Picker} from 'vant';
import StudentGradedAnswer from './StudentGradedAnswer.vue';
const {controller}=defineProps({controller:{type:Object,required:true}}),m=ref(controller.model),a=controller.actions,reveals=ref({}),expanded=ref([]),picker=ref(false),failedImage=ref(false),query=ref('');
const off=controller.subscribe(value=>m.value=value);onBeforeUnmount(off);
const original=computed(()=>m.value.questions.find(q=>q.number===m.value.original));
const graphGroups=computed(()=>m.value.groups.map(([title,id,items],index)=>({title,id,x:10+index*230,items:items.map(([id,title],i)=>({id,title,y:210+i*50,questions:m.value.filtered.filter(q=>q.concepts.includes(id))}))})));
function openOriginal(number){failedImage.value=false;a.original(number);}
function show(q,grading){const key=q.number+':'+(grading?'grade':'explain');reveals.value[key]=!reveals.value[key];if(reveals.value[key])a[grading?'grade':'explain'](q.number);}
const verdict=key=>({correct:'正确',partial:'部分正确',incorrect:'需要订正',unanswered:'未作答',review:'待人工核对'})[key]||'尚无有效批改';
const format=s=>window.GrowingMathFormat.html(String(s||''));
</script>
<template>
 <main class="student-midterm" :data-kind="m.kind">

  <header v-if="m.kind==='original'"><h1>文景实验学校八年级上数学期中复习卷（1）</h1><p>班级：______　学号：______　姓名：______</p></header><h1 v-else>试卷 · 交互知识图谱</h1>
  <template v-if="m.kind==='original'">
   <template v-for="q in m.questions" :key="q.number"><h2 v-if="[1,9,16].includes(q.number)" class="original-section-heading">{{q.number===1?'一、选择题':q.number===9?'二、填空题':'三、解答题'}}</h2><article :id="'original-question-'+q.number" :data-number="q.number" class="midterm-question" :class="{'is-wrong':q.priority}">
    
    <div class="midterm-actions"><Button :aria-label="'第'+q.number+'题，原卷作答'" @click="openOriginal(q.number)">原卷作答</Button><Button v-if="q.priority&&!reveals[q.number+':explain']" :aria-controls="'midterm-explain-'+q.number" :aria-expanded="false" @click="show(q,false)">AI解答</Button><Button v-else-if="q.priority" :aria-controls="'midterm-explain-'+q.number" :aria-expanded="true" icon="cross" aria-label="关闭AI解答" class="midterm-close" @click="show(q,false)"/><Button v-if="q.canGrade&&!reveals[q.number+':grade']" :aria-controls="'midterm-grade-'+q.number" :aria-expanded="false" @click="show(q,true)">AI批改</Button><Button v-else-if="q.canGrade" :aria-controls="'midterm-grade-'+q.number" :aria-expanded="true" icon="cross" aria-label="关闭AI批改" class="midterm-close" @click="show(q,true)"/></div>
    <div class="midterm-readonly" v-html="q.html"/>
    <template v-for="kind in ['explain','grade']" :key="kind"><section v-if="reveals[q.number+':'+kind]" class="midterm-ai" :id="'midterm-'+kind+'-'+q.number" :aria-label="kind==='grade'?'原卷批改':'独立解答'"><p role="status">{{m.ai[q.number+':'+kind]?.status}}</p><Button v-if="m.ai[q.number+':'+kind]?.busy" @click="a.cancel(q.number+':'+kind)">{{kind==='grade'?'取消批改':'取消解答'}}</Button><Button v-else-if="!m.ai[q.number+':'+kind]?.text&&!m.ai[q.number+':'+kind]?.grade" @click="a[kind==='grade'?'grade':'explain'](q.number)">重试</Button><div v-if="m.ai[q.number+':'+kind]?.text" class="math-prose" v-html="m.ai[q.number+':'+kind].text"/><CellGroup v-if="kind==='explain'&&q.models.length"><Cell v-for="link in q.models" :key="link.id" :title="link.id+'号 · '+link.title" :label="link.note" :url="link.href" is-link/></CellGroup><StudentGradedAnswer v-if="m.ai[q.number+':'+kind]?.grade" :grade="{id:'original-review-'+q.number,kind:'initial',result:{...m.ai[q.number+':'+kind].grade,answerPages:[q.image]}}" :question="q" :paper="{pages:[]}" :render="format" grading-only/></section></template>
   </article></template>
   <Popup :show="m.original!==null" position="bottom" round class="midterm-original" @update:show="value=>!value&&a.closeOriginal()"><header><h2>第 {{m.original}} 题 · 原卷作答</h2><Button icon="cross" aria-label="关闭原卷作答" class="midterm-close" @click="a.closeOriginal"/></header><p v-if="failedImage" role="alert">原卷作答图片加载失败，请关闭后重试。</p><img v-else-if="original" :src="original.image" :alt="'第'+m.original+'题的原卷手写解答'" @error="failedImage=true"/></Popup>
  </template>
  <template v-else>
   <section class="personal-graph"><h2>我的拍照试卷 · 知识图谱</h2><div class="midterm-actions"><Button @click="a.refresh">刷新试卷</Button><Button v-if="m.students.length" @click="picker=true">学生：{{m.students.find(s=>s.id===m.studentId)?.username||'请选择学生'}} ⌄</Button></div><form v-if="m.students.length" @submit.prevent="a.search(query)"><Field v-model="query" label="搜索学生" maxlength="40"/><div class="midterm-actions"><Button native-type="submit">查询</Button><Button :disabled="m.page<=1" @click="a.page(-1)">上一页</Button><Button :disabled="m.page*m.pageSize>=m.total" @click="a.page(1)">下一页</Button></div></form><p role="status">{{m.message}}</p>
    <template v-if="m.profile"><div class="midterm-actions"><Button :type="m.selected==='all'?'primary':'default'" @click="a.personalFilter('all')">全部拍照题目 · {{m.profile.questions.length}}</Button><Button :type="m.selected==='pending'?'primary':'default'" @click="a.personalFilter('pending')">待核对 / 待归类</Button></div><Collapse v-model="expanded"><CollapseItem v-for="unit in m.profile.units.filter(u=>m.profile.questions.some(q=>q.unitIds.includes(u.id)))" :key="unit.id" :name="unit.id" :title="unit.title"><Button @click="a.personalFilter('u:'+unit.id)">单元全部题目</Button><div class="midterm-actions"><Button v-for="node in m.profile.nodes.filter(n=>n.unitId===unit.id&&m.profile.questions.some(q=>q.nodeIds.includes(n.id)))" :key="node.id" @click="a.personalFilter('n:'+node.id)">{{node.title}}</Button></div></CollapseItem></Collapse><article v-for="q in m.personalQuestions" :key="q.id" class="midterm-question"><Button @click="a.openPaper(q)">{{q.paperTitle}} · 第{{q.number}}题</Button><p>{{q.text}}</p><p :class="{'is-wrong':!q.pending&&['incorrect','partial'].includes(q.verdict)}">{{q.pending?'试卷 / 题目待核对':q.verdict?verdict(q.verdict):q.markedWrong?'原卷标记错题':'尚无有效批改'}}</p><CellGroup><Cell v-for="node in m.profile.nodes.filter(n=>q.nodeIds.includes(n.id))" :key="node.id" :title="node.title" :url="'../'+node.href" is-link/></CellGroup></article><p v-if="!m.personalQuestions.length">暂无对应题目。</p></template>
   </section>
   <h2>期中复习卷 · 固定资料</h2><p>23道可见题 · 5个教材单元 · 第19题待补充</p><p class="summary">只按原卷考查与可见作答痕迹整理，不把全部试题视为错题。第2题第三式分母末字母待核对。</p><p><Button tag="a" href="math-exam-midterm.html" class="graph-text-link">打开无答案试卷</Button>　<Button tag="a" :href="m.bank" class="graph-text-link">进入已归档题库</Button></p><p class="summary">点击图中单元进入课程；点击考点筛选题目；点击题号打开原题。每题下方提供对应单元知识点的学习链接。</p>
   <div class="midterm-map" tabindex="0" role="region" aria-label="考点关系图，可横向滚动"><svg viewBox="0 0 1150 940" role="img" aria-label="期中卷五类知识及题号图谱"><g fill="none" stroke="#aabeb1" stroke-width="2"><path v-for="group in graphGroups" :key="group.id" :d="`M575 74 V110 H${group.x+105} V145`"/></g><rect x="390" y="20" width="370" height="55" rx="12" fill="#234c3e"/><text x="575" y="55" fill="white" text-anchor="middle" font-size="22">期中复习卷 · 知识图谱</text><g v-for="group in graphGroups" :key="group.id"><a :href="(group.id==='math-8b-10'?'knowledge.html':'math-course.html')+'?chapter='+group.id" :aria-label="'打开'+group.title+'单元'"><rect :x="group.x" y="145" width="210" height="50" rx="9" fill="#dce9df"/><text :x="group.x+105" y="178" text-anchor="middle" font-size="20">{{group.title}} ↗</text></a><g v-for="node in group.items" :key="node.id"><g role="button" tabindex="0" :aria-label="'查看'+node.title+'对应题目'" @click="a.concept(node.id)" @keydown.enter.prevent="a.concept(node.id)" @keydown.space.prevent="a.concept(node.id)"><rect :x="group.x" :y="node.y" width="210" height="43" rx="7" fill="white" :stroke="m.concept===node.id?'#234c3e':'#dce3df'"/><text :x="group.x+10" :y="node.y+18" font-size="13">{{node.title.length>16?node.title.slice(0,15)+'…':node.title}}</text></g><a v-for="(q,index) in node.questions" :key="q.id" :href="m.bank+'#'+q.id" :aria-label="'打开第'+q.number+'题'"><text :x="group.x+10+index*31" :y="node.y+35" font-size="11" fill="#275e4d" text-decoration="underline">{{q.number}}</text></a></g></g></svg></div>
   <div class="midterm-actions"><Button :type="m.concept==='all'?'primary':'default'" @click="a.concept('all')">全部题目</Button></div><section v-for="([name,id,items]) in m.groups" :key="id"><h3>{{name}}</h3><div class="midterm-actions"><Button v-for="([key,label]) in items" :key="key" :type="m.concept===key?'primary':'default'" @click="a.concept(key)">{{label}}</Button></div></section>
   <h2>{{m.names[m.concept]||'全部知识点'}} · {{m.filtered.length}} 道题</h2><CellGroup v-if="m.selectedLinks.length"><Cell v-for="link in m.selectedLinks" :key="link.node" :title="link.label" :url="link.href" is-link/></CellGroup><div class="midterm-actions" v-for="([from,to],i) in m.selectedPaths" :key="i"><Button @click="a.concept(from)">{{m.names[from]}}</Button> → <Button @click="a.concept(to)">{{m.names[to]}}</Button></div>
   <article v-for="q in m.filtered" :key="q.id" class="midterm-question"><h3>第 {{q.number}} 题 · {{q.title}}</h3><p :class="{'is-wrong':q.priority}">{{q.review}}</p><CellGroup><Cell v-for="unit in q.units" :key="unit.id" :title="'归档单元：'+unit.title" :url="unit.href" is-link/></CellGroup><section v-for="concept in q.links" :key="concept.id"><Button @click="a.concept(concept.id)">{{concept.title}}</Button><CellGroup><Cell v-for="link in concept.targets" :key="link.node" :title="link.label" :url="link.href" is-link/></CellGroup></section><Button tag="a" :href="m.bank+'#'+q.id">查看本题与题设图</Button></article>
   <Popup v-model:show="picker" position="bottom" round><Picker :columns="m.students.map(s=>({text:s.username||'当前账号',value:s.id}))" @confirm="a.student($event.selectedValues[0]);picker=false" @cancel="picker=false"><template #cancel><Button icon="cross" aria-label="关闭学生选择" class="midterm-close" @click="picker=false"/></template></Picker></Popup>
  </template>
 </main>
</template>
<style scoped>
.student-midterm{--van-primary-color:#22634b;max-width:1080px;margin:auto;padding:24px clamp(16px,4vw,36px) 60px;color:#24352e;font-family:system-ui,-apple-system,'Microsoft YaHei',sans-serif;overflow-wrap:anywhere}.student-midterm,.student-midterm :deep(*){box-sizing:border-box}.student-midterm nav,.midterm-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}.student-midterm header{padding:20px 0}.student-midterm h1{font-size:clamp(26px,4vw,36px);line-height:1.4}.student-midterm p{line-height:1.8}.student-midterm :deep(.van-button){min-height:44px;font:inherit;text-decoration:none}.student-midterm :deep(.van-cell){padding:16px}.midterm-question{padding:26px 0;border-top:1px solid #dce4dc}.midterm-readonly{line-height:1.9;min-width:0}.midterm-readonly :deep(svg){display:block;max-width:100%;height:auto;margin:16px auto}.midterm-readonly :deep(img){max-width:100%;height:auto}.midterm-readonly :deep(.katex-display),.math-prose :deep(.katex-display){overflow-x:auto;overflow-y:hidden;max-width:100%}.midterm-close.van-button{width:44px;height:44px;padding:0;flex:0 0 44px}.midterm-original{height:90dvh;overflow:auto;padding:0 20px 30px;color:#24352e}.midterm-original header{display:flex;align-items:center;justify-content:space-between;gap:12px}.midterm-original h2{font-size:20px}.midterm-original img{display:block;max-width:100%;height:auto;margin:auto}.midterm-ai{padding:20px 0;line-height:1.9}.is-wrong{color:#b42318}.is-wrong .midterm-actions{color:#24352e}.personal-graph{padding-bottom:24px;border-bottom:1px solid #dce4dc}.midterm-map{overflow:auto;max-height:550px;overscroll-behavior:contain}.midterm-map svg{width:740px;display:block}.student-midterm :deep(.van-field__control){background:transparent;padding:0;border:0;box-shadow:none;font:inherit}.student-midterm :deep(.van-button__text){white-space:normal}.student-midterm :deep(.van-button){height:auto}.student-midterm :deep(.van-collapse-item__content){padding:16px}.student-midterm .midterm-close{height:44px}
</style>

<style scoped>
