.student-midterm{font:16px/1.7 "Segoe UI","Microsoft YaHei",system-ui,sans-serif;color:#25332c;max-width:1180px;padding:24px;margin:auto;overflow-wrap:anywhere}.student-midterm[data-kind=original]{font-size:17px;max-width:980px;margin:24px auto;padding:40px;background:#fff}.student-midterm[data-kind=original]>header{padding:0}.student-midterm h1{font-size:26px;line-height:1.4;margin:.67em 0;font-weight:600}.student-midterm[data-kind=original] h1{text-align:center}.student-midterm p{line-height:1.7;margin:1em 0}.student-midterm[data-kind=original] header p{margin:17px 0}.student-midterm h2{font-size:20px;line-height:1.5;margin:30px 0 16.6px}.student-midterm[data-kind=original] .original-section-heading{padding-top:18px;border-bottom:1px solid #bbb;margin:16.6px 0}.student-midterm[data-kind=original] .midterm-question{position:relative;display:flow-root;padding:14px 0;border:0;margin:0;break-inside:avoid}.midterm-readonly{line-height:1.7}.student-midterm[data-kind=original] .midterm-question>.midterm-actions{float:right;justify-content:flex-end;max-width:100%;margin:0 0 8px 12px;gap:6px}.midterm-readonly :deep(.text){white-space:pre-wrap}.midterm-readonly :deep(figure){margin:15px auto;text-align:center}.midterm-readonly :deep(figure img){width:380px;max-width:100%;max-height:300px}.midterm-readonly :deep(figure svg){margin:15px auto}.midterm-readonly :deep(.work){height:90px}.midterm-readonly :deep(.note){font-size:13px;color:#555}.midterm-readonly :deep(.math-display){display:block;overflow-x:auto}.student-midterm[data-kind=original] .midterm-question[data-number="23"] :deep(.work),.student-midterm[data-kind=original] .midterm-question[data-number="24"] :deep(.work){height:180px}.student-midterm[data-kind=original] .midterm-question[data-number="24"] :deep(figure svg),.midterm-readonly :deep(figure svg.composite){width:100%;max-height:none}.midterm-readonly :deep(.katex){font-size:1.1em}.student-midterm :deep(.van-button){min-height:44px;height:auto;padding:9px 12px;border:1px solid #b1c4b6;border-radius:8px;background:#fff;color:inherit;font:inherit;line-height:1.5;box-shadow:none}.student-midterm[data-kind=original] .midterm-actions :deep(.van-button){font-size:14px;background:#fffefa}.student-midterm :deep(.van-button--primary){background:#234c3e;border-color:#234c3e;color:white}.student-midterm>nav{margin:0 0 16px;gap:8px}.student-midterm>nav :deep(.van-button),.student-midterm :deep(.graph-text-link){border:0;padding:4px;background:transparent;color:#275e4d;text-decoration:underline;text-underline-offset:3px}.personal-graph{padding:18px;margin:24px 0;border:1px solid #b1c4b6;border-radius:12px;background:#f7faf7}.personal-graph h2{margin:0 0 14px}.summary{color:#5b6c61}.midterm-map{border:1px solid #dde5dd;border-radius:15px;background:#f7faf7;max-height:none}.midterm-map svg{min-width:900px;width:100%;font-family:inherit}.student-midterm[data-kind=graph] .midterm-question{padding:18px;border:1px solid #dde5dd;border-radius:12px;background:white;margin:12px 0}.student-midterm[data-kind=graph] .midterm-question h3{margin:0}.student-midterm :deep(.van-cell){font:inherit;background:transparent;padding:8px 10px}.midterm-ai{clear:both}.student-midterm .midterm-close{width:44px;height:44px;padding:0;flex:0 0 44px}.midterm-original h2{margin:16px 0}.midterm-original header{padding:0}
